34	public class Eth1DataCache {
35	  static final String CACHE_SIZE_METRIC_NAME = "eth1_block_cache_size";
36	  static final String VOTES_MAX_METRIC_NAME = "eth1_current_period_votes_max";
37	  static final String VOTES_TOTAL_METRIC_NAME = "eth1_current_period_votes_total";
38	  static final String VOTES_UNKNOWN_METRIC_NAME = "eth1_current_period_votes_unknown";
39	  static final String VOTES_CURRENT_METRIC_NAME = "eth1_current_period_votes_current";
40	  static final String VOTES_BEST_METRIC_NAME = "eth1_current_period_votes_best";
41	
42	  private final UInt64 cacheDuration;
43	  private final Eth1VotingPeriod eth1VotingPeriod;
44	
45	  private final NavigableMap<UInt64, Eth1DataAndHeight> eth1ChainCache =
46	      new ConcurrentSkipListMap<>();
47	  private final SettableGauge currentPeriodVotesTotal;
48	  private final SettableGauge currentPeriodVotesUnknown;
49	  private final SettableGauge currentPeriodVotesCurrent;
50	  private final SettableGauge currentPeriodVotesBest;
51	  private final SettableGauge currentPeriodVotesMax;
52	
53	  public Eth1DataCache(final MetricsSystem metricsSystem, final Eth1VotingPeriod eth1VotingPeriod) {
54	    this.eth1VotingPeriod = eth1VotingPeriod;
55	    cacheDuration = eth1VotingPeriod.getCacheDurationInSeconds();
56	    metricsSystem.createIntegerGauge(
57	        TekuMetricCategory.BEACON,
58	        CACHE_SIZE_METRIC_NAME,
59	        "Total number of blocks stored in the Eth1 block cache",
60	        this::size);
61	    currentPeriodVotesMax =
62	        SettableGauge.create(
63	            metricsSystem,
64	            TekuMetricCategory.BEACON,
65	            VOTES_MAX_METRIC_NAME,
66	            "Maximum number of votes that can possibly be cast in the current Eth1 voting period");
67	    currentPeriodVotesTotal =
68	        SettableGauge.create(
69	            metricsSystem,
70	            TekuMetricCategory.BEACON,
71	            VOTES_TOTAL_METRIC_NAME,
72	            "Total number of votes cast in the current Eth1 voting period");
73	    currentPeriodVotesUnknown =
74	        SettableGauge.create(
75	            metricsSystem,
76	            TekuMetricCategory.BEACON,
77	            VOTES_UNKNOWN_METRIC_NAME,
78	            "Number of votes for locally unknown Eth1 blocks in the current Eth1 voting period");
79	    currentPeriodVotesCurrent =
80	        SettableGauge.create(
81	            metricsSystem,
82	            TekuMetricCategory.BEACON,
83	            VOTES_CURRENT_METRIC_NAME,
84	            "Number of votes for the current Eth1 data in the current Eth1 voting period");
85	    currentPeriodVotesBest =
86	        SettableGauge.create(
87	            metricsSystem,
88	            TekuMetricCategory.BEACON,
89	            VOTES_BEST_METRIC_NAME,
90	            "Number of votes for the leading block in the current Eth1 voting period");
91	  }
